INSERT INTO roles (name) SELECT 'CUSTOMER' WHERE NOT EXISTS (SELECT 1 FROM roles WHERE name='CUSTOMER');
INSERT INTO roles (name) SELECT 'ADMIN' WHERE NOT EXISTS (SELECT 1 FROM roles WHERE name='ADMIN');
INSERT INTO permissions (name) SELECT 'ADMIN_ACCESS' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE name='ADMIN_ACCESS');
INSERT INTO permissions (name) SELECT 'USER_READ' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE name='USER_READ');
INSERT INTO permissions (name) SELECT 'USER_WRITE' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE name='USER_WRITE');
INSERT INTO permissions (name) SELECT 'CATALOG_WRITE' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE name='CATALOG_WRITE');
INSERT INTO permissions (name) SELECT 'ORDER_WRITE' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE name='ORDER_WRITE');
INSERT INTO user_roles (user_id, role_id) SELECT u.id,r.id FROM users u JOIN roles r ON r.name=u.role WHERE NOT EXISTS (SELECT 1 FROM user_roles x WHERE x.user_id=u.id AND x.role_id=r.id);
INSERT INTO role_permissions (role_id, permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON r.name='ADMIN' WHERE NOT EXISTS (SELECT 1 FROM role_permissions x WHERE x.role_id=r.id AND x.permission_id=p.id);
